69:     @EventListener(ApplicationReadyEvent.class)
70:     public void onApplicationReady(ApplicationReadyEvent event) {
71:         // Maintenance CLIs also publish ApplicationReadyEvent with the local profile.
72:         // Only the running loopback web application owns the daily scheduler.
73:         if (!(event.getApplicationContext() instanceof org.springframework.web.context.WebApplicationContext web)
74:                 || web.getServletContext() == null
75:                 || !"127.0.0.1".equals(environment.getProperty("server.address"))) {
76:             runtimeReason="J3_WEB_APPLICATION_REQUIRED";return;
77:         }
78:         start();
79:     }
80: 
81:     public void start() {
82:         if(!executionEnabled || !environment.acceptsProfiles(Profiles.of("local"))) {
83:             runtimeReason="J3_RUNTIME_DISABLED";return;
84:         }
85:         // Offline reconstruction precedes the first daily success decision. No transport is opened here.
86:         if(!orders.lead(owner,J3RuntimeService::ownerMayBeAlive)) {runtimeReason="J3_OTHER_PROCESS_OWNER";return;}
87:         try {
88:             for(Order interrupted:orders.interrupted(owner)) {
89:                 if(ownerMayBeAlive(interrupted.owner())) continue;
90:                 completion.interrupt(interrupted.id(),interrupted.owner(),Instant.now(),"OWNER_PROCESS_ABSENT");
91:             }
92:             recovery.recover();
93:             ready=true;runtimeReason=null;
94:             ticker.scheduleWithFixedDelay(this::tickSafely,0,500,TimeUnit.MILLISECONDS);
95:         } catch(RuntimeException failure) {
96:             runtimeReason="J3_STARTUP_RECONCILIATION_FAILED";
97:             // Keep leadership: startup failure does not authorize a different process to collect.
98:         }
99:     }
