124:     public String providerUnavailableReason() {
125:         var access=qualification.snapshot();
126:         if(!access.available()) return access.blockers().getFirst();
127:         var state=resilience.snapshot();
128:         if(state.state()==ProviderResilienceData.State.SUSPENDED) return "PROVIDER_SUSPENDED";
129:         var ownership=guard.snapshot();
130:         if(ownership!=null && "CLEANUP_REQUIRED".equals(ownership.state())) return "PROVIDER_CLEANUP_REQUIRED";
131:         boolean currentOwner=ownership!=null && "OWNED".equals(ownership.state()) && ownership.owner()!=null
132:                 && ownership.owner().instanceId().equals(coordinator.instanceOwner().instanceId());
133:         if(state.unresolvedDispatchId()!=null && !currentOwner) return "PROVIDER_DEPARTURE_UNRESOLVED";
134:         if(ownership!=null && "OWNED".equals(ownership.state()) && !currentOwner) return "PROVIDER_OTHER_PROCESS_OWNER";
135:         String liveReason=live.j3AvailabilityReason();
136:         if(liveReason!=null) return liveReason;
137:         return null;
138:     }
