45:                 .addValue("json", JSON.writeValueAsString(page));
46:         // The run lock serializes append against terminal publication and duplicate completion.
47:         jdbc.queryForObject("select run_id from j3_collection_run where run_id=:id for update", p, UUID.class);
48:         List<Boolean> existing = jdbc.query("""
49:                 select evidence=cast(:json as jsonb) from j3_collection_page where run_id=:id and page=:page
50:                 """, p, (rs, n) -> rs.getBoolean(1));
51:         if (!existing.isEmpty()) {
52:             if (!existing.getFirst()) throw new IllegalStateException("J3_PAGE_IDENTITY_CONFLICT");
53:             return;
54:         }
55:         jdbc.update("""
56:                 insert into j3_collection_page(run_id,page,snapshot_id,evidence)
57:                 values (:id,:page,:snapshot,cast(:json as jsonb))
58:                 """, p);
59:     }
