61:     @Override @Transactional
62:     public void publish(Proof proof, List<Entry> entries) {
63:         // Shared with admission: a manual success committed before a daily claim prevents its dispatch.
64:         jdbc.queryForObject("select pg_advisory_xact_lock(-6060)",Map.of(),Object.class);
65:         var p = params(proof.runId()).addValue("state", proof.state().name())
66:                 .addValue("finish", ts(proof.finishedAt())).addValue("code", proof.terminalCode())
67:                 .addValue("date", proof.date());
68:         String state = jdbc.queryForObject("select state from j3_collection_run where run_id=:id for update", p, String.class);
69:         if (!"RUNNING".equals(state)) {
