71:             // JSONB compares timestamps/metadata independent of Java map iteration order.
72:             Proof normalized = new Proof(proof.runId(),proof.date(),proof.trigger(),micros(proof.startedAt()),
73:                     micros(proof.finishedAt()),proof.state(),proof.terminalCode(),proof.pages());
74:             if (!existing.proof().equals(normalized) || !new java.util.HashSet<>(existing.entries()).equals(new java.util.HashSet<>(entries)))
75:                 throw new IllegalStateException("J3_TERMINAL_IDENTITY_CONFLICT");
76:             return;
77:         }
78:         var row = jdbc.queryForMap("select collection_date,trigger_kind,started_at from j3_collection_run where run_id=:id", p);
79:         if (!row.get("collection_date").toString().equals(proof.date().toString())
80:                 || !row.get("trigger_kind").equals(proof.trigger().name())
81:                 || !((Timestamp) row.get("started_at")).toInstant().equals(micros(proof.startedAt())))
