89:                     select s.payload_raw is not null from provider_snapshot s join j3_collection_page p on p.snapshot_id=s.id
90:                     where p.run_id=:id for share of s
91:                     """, p, (rs, n) -> rs.getBoolean(1));
92:             if (rawPresent.size() != proof.pages().size() || rawPresent.contains(false))
