102:                 }
103:             }
104:         }
105:         jdbc.update("update j3_collection_run set state=:state,finished_at=:finish,terminal_code=:code where run_id=:id", p);
106:         if (proof.successful()) {
107:             jdbc.update("""
108:                     insert into j3_last_success(collection_date,run_id,revision) values (:date,:id,1)
109:                     on conflict (collection_date) do update set run_id=excluded.run_id,revision=j3_last_success.revision+1
110:                     where (select finished_at from j3_collection_run where run_id=j3_last_success.run_id) <= :finish
