196:                         r.snapshot_occurrence_id,
197:                         case when r.snapshot_occurrence_id is null then s.requested_at else o.requested_at end requested_at,
198:                         case when r.snapshot_occurrence_id is null then s.received_at else o.received_at end received_at,
199:                         case when r.snapshot_occurrence_id is null then s.latency_ms else o.latency_ms end latency_ms,
200:                         o.persistence_outcome
201:                     from j8_benchmark_unit u left join j8_benchmark_unit_result r on r.unit_id=u.id
202:                     left join provider_snapshot s on s.id=r.snapshot_id
203:                     left join provider_snapshot_occurrence o on o.id=r.snapshot_occurrence_id and o.snapshot_id=r.snapshot_id
204:                     where u.campaign_id=:id order by u.unit_ordinal
205:                     """, params(id), (p,m) -> new LegacyPage(p.getInt(1),p.getString(2),p.getString(3),p.getString(4),
206:                     p.getObject(5,Long.class),p.getString(6),instant(p,7),p.getObject(8,Long.class),
207:                     instant(p,9),instant(p,10),p.getObject(11,Long.class),p.getString(12)));
208:             return new Legacy(id,r.getObject("collection_date",LocalDate.class),r.getTimestamp("started_at").toInstant(),
209:                     r.getTimestamp("finished_at").toInstant(),r.getInt("completed_units"),r.getInt("maximum_units"),pages);
210:         });
211:     }
212:     @Override @Transactional(readOnly=true)
213:     public Optional<CatalogPage> page(UUID id,LocalDate date,int page,int pageSize) {
214:         if(page<1 || page>1_000_000 || (pageSize!=25 && pageSize!=50 && pageSize!=100))
215:             throw new IllegalArgumentException("J3_PAGINATION_INVALID");
216:         var p=params(id).addValue("date",date).addValue("limit",pageSize).addValue("offset",(long)(page-1)*pageSize);
217:         var completed=jdbc.query("select finished_at from j3_collection_run where run_id=:id and collection_date=:date and state='COMPLETED'",
218:                 p,(r,n)->r.getTimestamp(1).toInstant());
219:         if(completed.isEmpty())return Optional.empty();
220:         long total=jdbc.queryForObject("select count(*) from j3_catalog_entry where run_id=:id",p,Long.class);
221:         if(page>Math.max(1,(total+pageSize-1)/pageSize))throw new IllegalArgumentException("J3_PAGE_OUT_OF_RANGE");
222:         var entries=jdbc.query("""
223:             select entry::text from j3_catalog_entry where run_id=:id
224:             order by entry->>'category' collate "C",entry->>'name' collate "C",tournament_id limit :limit offset :offset
225:             """,p,(row,n)->JSON.readValue(row.getString(1),Entry.class));
226:         return Optional.of(new CatalogPage(id,date,completed.getFirst(),page,pageSize,total,entries));
227:     }
228:     @Override
229:     public void recordRecovery(Legacy source, String status, String reason, Instant recoveredAt) {
230:         jdbc.update("""
231:                 insert into j3_legacy_recovery(campaign_id,collection_date,finished_at,status,reason,recovered_at)
232:                 values(:id,:date,:finish,:status,:reason,:recovered) on conflict(campaign_id) do nothing
233:                 """, params(source.campaignId()).addValue("date",source.date()).addValue("finish",ts(source.finishedAt()))
234:                 .addValue("status",status).addValue("reason",reason).addValue("recovered",ts(recoveredAt)));
235:     }
236:     private static MapSqlParameterSource params(UUID id) { return new MapSqlParameterSource("id",id); }
237:     private static Instant instant(ResultSet row,int column) throws SQLException {
238:         Timestamp value=row.getTimestamp(column); return value==null?null:value.toInstant();
239:     }
240:     private static Instant micros(Instant value) { return value.truncatedTo(java.time.temporal.ChronoUnit.MICROS); }
241:     private static Timestamp ts(Instant value) { return Timestamp.from(micros(value)); }
242: }

