19: /** All J3 entry points share this bounded execution path; no legacy stop/intent mutations. */
20: @Service
21: public class J3CollectionExecutor {
22:     /** Implementations own cleanup; the dispatch callback runs only after the provider guard and delay. */
23:     public interface ProviderAccess extends AutoCloseable {
24:         ScheduledEventsTransportResponse execute(ScheduledEventsProviderPageRequest request,Runnable beforeDispatch);
25:         @Override void close();
