30:     private final J3CollectionCompletionService completion;private final J8BenchmarkAuditService benchmark;
31:     private final Duration cacheTtl;private final Clock clock;
32:     @Autowired public J3CollectionExecutor(RawManualCallSnapshotStore raw,J3ScheduledEventsPageCache cache,
33:             J3CollectionStore collections,J3CatalogProjector projector,J3CollectionCompletionService completion,
34:             J8BenchmarkAuditService benchmark,SofascoreEndpointCatalog catalog) {
