42:     public Result execute(Order order,URI origin,List<RawPayloadEvidence> imported,ProviderAccess provider,Supplier<String> cancellation) {
43:         boolean local=order.trigger()==Trigger.MANUAL_IMPORT;
44:         if(local) {
45:             imported=J3LocalBatchValidator.validate(order.date(),imported);
46:             if(provider!=null || !J3LocalBatchValidator.fingerprint(imported).equals(order.inputSha256()))
47:                 throw new IllegalArgumentException("J3_IMPORT_IDENTITY_CONFLICT");
48:         } else if(provider==null || imported!=null)throw new IllegalArgumentException("J3_PROVIDER_ACCESS_REQUIRED");
49:         Instant started=clock.instant();
50:         var circuit=J3NetworkCircuit.forAcceptedCollection(started);
51:         var processor=new J3ScheduledEventsOutcomeProcessor(raw,new ScheduledEventsV1Parser(),circuit);
52:         var pages=new ArrayList<J3MinimizedPageEvidence>();
53:         J8BenchmarkAuditService.Session audit=null;J8BenchmarkAuditService.Unit pending=null;
54:         State state=State.FAILED;String code="PROCESSING_FAILURE";boolean fatal=false;
55:         List<Entry> entries=List.of();
56:         try {
57:             collections.begin(order.id(),order.date(),order.trigger(),started);
58:             audit=benchmark.start(order.id(),J8BenchmarkCampaignType.J3_SCHEDULED_EVENTS,
59:                     local?J8BenchmarkExecutionMode.MANUAL_LOCAL_JSON_IMPORT:J8BenchmarkExecutionMode.GUARDED_PROVIDER,35,Optional.of(order.date()));
60:             for(int number=1;number<=35;number++) {
61:                 String cancelled=cancellation.get();
62:                 if(cancelled!=null) {code=cancelled;state=State.CANCELLED;break;}
63:                 if(!clock.instant().isBefore(order.deadline())) {code="ADMISSION_DEADLINE_EXPIRED";state=State.CANCELLED;break;}
64:                 String key="SCHEDULED_EVENTS|date="+order.date()+"|page="+number;
65:                 pending=audit.declare(number,SofascoreEndpointType.SCHEDULED_EVENTS,key,Optional.empty(),OptionalLong.empty());
