148:     private static J3MinimizedPageEvidence evidence(int number,ScheduledEventsTransportResponse response,J3ScheduledEventsOutcome outcome,boolean local) {
149:         var saved=outcome.persistence().orElseThrow();Boolean next=outcome.hasNextPage().orElse(null);
