153:                 :"UNEXPECTED_CONTENT".equals(reason)?RawSnapshotSchemaStatus.UNEXPECTED_CONTENT:RawSnapshotSchemaStatus.TRANSPORT_ERROR;
154:         return (local?J3MinimizedPageEvidence.imported(number,response,saved,schema,next,reason)
155:                 :J3MinimizedPageEvidence.recorded(number,response,saved,schema,next,reason)).withOccurrence(saved.occurrenceId().orElseThrow());
156:     }
157:     private static final class Cancelled extends RuntimeException {Cancelled(String code){super(code);}}
158: }

