785:         state.ioLock.lock();
786:         try {
787:             requireActive(state);state.j3Scope=scope;state.lastJ3Page=0;
788:             state.socket.setSoTimeout(toMillis(properties.getStartupTimeout()));
789:             state.output.writeByte(BEGIN_J3);state.output.writeUTF(scope.runId().toString());
790:             state.output.writeUTF(scope.date().toString());state.output.writeLong(scope.deadline().toEpochMilli());state.output.flush();
791:             requireScopeAcknowledgement(state,J3_READY,scope);
792:             state.liveGroups.abandonForJ3();
793:         } catch(IOException failure) {throw new PlaywrightProviderException(PlaywrightProviderFailure.PROTOCOL_ERROR,failure);}
794:         finally {state.ioLock.unlock();}
795:         return new PlaywrightProviderCampaign() {
796:             private boolean closed;
797:             @Override public PlaywrightProviderResponse execute(PlaywrightProviderRequest request) {
798:                 return execute(request,PlaywrightDispatchAdmission.UNRESTRICTED);
799:             }
800:             @Override public PlaywrightProviderResponse execute(PlaywrightProviderRequest request,PlaywrightDispatchAdmission admission) {
801:                 if(closed)throw new PlaywrightProviderException(PlaywrightProviderFailure.OPERATOR_STOP);
802:                 return ChildJvmPlaywrightProviderSupervisor.this.execute(state,request,admission,null,scope);
803:             }
804:             @Override public void close() {if(!closed){endJ3(state,scope);closed=true;}}
805:         };
806:     }
807: 
808:     private void endJ3(CampaignState state,J3ProviderSubOperation scope) {
809:         if(state.controlOwner!=Thread.currentThread() || !scope.equals(state.j3Scope))
810:             throw new PlaywrightProviderException(PlaywrightProviderFailure.INVALID_REQUEST);
811:         state.ioLock.lock();
812:         try {
813:             requireActive(state);state.socket.setSoTimeout(toMillis(properties.getGracefulCloseTimeout()));
814:             state.output.writeByte(END_J3);state.output.writeUTF(scope.runId().toString());state.output.flush();
815:             requireScopeAcknowledgement(state,J3_CLOSED,scope);
816:             state.j3Scope=null;state.lastJ3Page=0;
817:         } catch(IOException failure) {throw new PlaywrightProviderException(PlaywrightProviderFailure.PROTOCOL_ERROR,failure);}
818:         finally {state.ioLock.unlock();}
819:     }
820:     private static void requireScopeAcknowledgement(CampaignState state,int expected,J3ProviderSubOperation scope)throws IOException {
821:         int frame=state.input.readUnsignedByte();
822:         if(frame==FAILURE)throw workerFailure(state.input.readUTF());
823:         if(frame!=expected || !scope.runId().toString().equals(state.input.readUTF()))
824:             throw new PlaywrightProviderException(PlaywrightProviderFailure.PROTOCOL_ERROR);
825:     }
826: 
827:     /** Progress frames cannot restart the configured whole-request deadline. */
1200:     private void requireActive(CampaignState state) {
1201:         ProcessRegistration registration = state.processRegistration.getNow(null);
1202:         if (active.get() != state
1203:                 || state.terminationRequested.get()
1204:                 || lifecycle.get() != SupervisorLifecycle.OPEN
1205:                 || registration == null
1206:                 || !registration.identityComplete()
1207:                 || !sameProcess(
1208:                         registration.process().toHandle(),
1209:                         registration.processStartedAt())) {
1210:             throw new PlaywrightProviderException(PlaywrightProviderFailure.OPERATOR_STOP);
1211:         }
1212:     }
