1214:     private Path requireWorkerJar() {
1215:         Path configured = properties.getWorkerJar();
1216:         if (configured == null) {
1217:             throw new PlaywrightProviderException(
1218:                     PlaywrightProviderFailure.WORKER_ARTIFACT_INVALID);
1219:         }
1220:         try {
1221:             Path real = configured.toAbsolutePath().normalize().toRealPath();
1222:             if (!Files.isRegularFile(real)
1223:                     || !real.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".jar")) {
1224:                 throw new PlaywrightProviderException(
1225:                         PlaywrightProviderFailure.WORKER_ARTIFACT_INVALID);
1226:             }
1227:             return real;
1228:         }
1229:         catch (IOException exception) {
1230:             throw new PlaywrightProviderException(
1231:                     PlaywrightProviderFailure.WORKER_ARTIFACT_INVALID, exception);
1232:         }
1233:     }
