1236:         ServerSocket server = new ServerSocket();
1237:         server.setReuseAddress(false);
1238:         server.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"), 0), 1);
1239:         server.setSoTimeout(toMillis(properties.getStartupTimeout()));
1240:         return server;
1241:     }
